X(85, "História", "América Latina", "<p>As Mães da Praça de Maio procuravam os filhos desaparecidos durante a ditadura argentina (1976–1983). O movimento expôs ao mundo a repressão do Estado, com sequestros, tortura e desaparecimentos: a <strong>violação dos direitos humanos</strong>. Alternativa <strong>A</strong>.</p><p>Os desaparecidos eram opositores do regime, não jovens da periferia (B); o tema não é violência doméstica (C) nem desigualdade (D); e a ditadura suprimiu, não relativizou, a democracia (E).</p>",
  tags=["ditadura argentina", "Mães da Praça de Maio"])
X(86, "Geografia", "Espaço urbano", "<p>Entre 2000 e 2020, as imagens de Dubai mostram ilhas artificiais em forma de palmeira e de mapa-múndi e uma grande expansão urbana sobre o deserto e o mar. É a <strong>artificialização do espaço geográfico</strong>. Alternativa <strong>D</strong>.</p><p>Não há desertificação (B), mudança de fronteira (C) ou de clima (E), e as obras transformam, não conservam, os lugares (A).</p>",
  figs(("q86a", "Imagem de satélite de Dubai em 2000: litoral reto, com um porto e pouca ocupação urbana ao longo da costa, cercada de deserto."),
       ("q86b", "Imagem de satélite de Dubai em 2020: cidade muito maior ao longo da costa e ilhas artificiais no mar, duas em forma de palmeira e um conjunto em forma de mapa-múndi.")),
  ["Dubai", "ilhas artificiais"])
X(87, "Filosofia", "Filosofia política", "<p>Ortega y Gasset diz que, na democracia, o poder público pertence à “coletividade dos cidadãos”: “mandemos todos”. O que sustenta o poder é a <strong>soberania popular</strong>. Alternativa <strong>A</strong>.</p><p>O texto não fala de classes, capital, propriedade ou centralização (B a E).</p>",
  tags=["democracia", "Ortega y Gasset"])
X(88, "Geografia", "Espaço urbano", "<p>O texto propõe “soluções baseadas na natureza” contra inundações, alagamentos e ondas de calor. <strong>Parques públicos</strong>, com vegetação e solo permeável, absorvem a água da chuva e diminuem o calor. Alternativa <strong>C</strong>.</p><p>Faixas, incineração, verticalização e estacionamentos (A, B, D e E) não atenuam esses problemas, e alguns os agravam ao impermeabilizar o solo.</p>",
  tags=["adaptação climática", "áreas verdes"])
X(89, "Geografia", "Geopolítica", "<p>No Conselho de Segurança, cinco países são membros permanentes e podem vetar qualquer resolução, poder que os outros dez não têm. Isso revela <strong>assimetria política</strong> entre os países. Alternativa <strong>B</strong>.</p><p>O veto contraria igualdade, consenso, equilíbrio e soberania compartilhada (A, C, D e E).</p>",
  tags=["ONU", "Conselho de Segurança"])
X(90, "Sociologia", "Trabalho", "<p>Castoriadis aponta que o capitalismo tenta reduzir o trabalhador a uma peça de máquina, mas não funciona sem a iniciativa humana desse mesmo trabalhador. A contradição está na <strong>alienação decorrente da organização do trabalho</strong>, que desumaniza quem precisa continuar agindo como humano. Alternativa <strong>C</strong>.</p><p>O texto não fala de obsolescência tecnológica (A), gestão de conflitos (B) ou igualdade (D), e o capitalismo tenta reduzir, não fortalecer, a autonomia (E).</p>",
  tags=["Castoriadis", "alienação"])

